async () => { const get=async(url,pages,idx,re)=>{ const h=await (await fetch(url)).text(); const vs=new DOMParser().parseFromString(h,'text/html').querySelector('[name=__VIEWSTATE]').value; const out=[]; for(let p=1;p<=pages;p++){ const t=await (await fetch(url,{method:'POST',body:new URLSearchParams({__EVENTTARGET:'gv',__EVENTARGUMENT:'Page$'+p,__VIEWSTATE:vs})})).text(); const d=new DOMParser().parseFromString(t,'text/html'); [...d.querySelectorAll('tr')].forEach(r=>{const c=[...r.children].map(x=>x.textContent.trim()); if(re.test(c[1]||'')) out.push(c.slice(1,4).join(' | '));}); } return out; };
const res=await get('/Residents.aspx',16,2,/\S/).then(a=>a.filter(s=>/^[A-Z][a-z]+ \w+ \| \d{4}/.test(s)));
const dev=await get('/Devices.aspx',17,2,/^D\d+$/);
return {residentCount:res.length, res:res.filter(s=>/\| (1004|1011|1026|1003|1005|1010|1012) \|/.test(s)), deviceCount:dev.length, dev:dev.filter(s=>/\| (1004|1011|1026) \|/.test(s))}; }

